value.fa:
// گام مشخص (نزولی)
برای (عدد شمارنده = 10; شمارنده > 0; گام 2) {
    چاپ(شمارنده);
}

// گام هوشمند (خالی = تشخیص خودکار جهت و گام 1)
برای (عدد شمارنده = 0; شمارنده < 4;) {
    چاپ("  شمارنده = " + شمارنده);
}

// گام مشخص (منطق صعودی/نزولی توسط کامپایلر)
برای (عدد شمارنده = 34; شمارنده > 3; گام 3) {
    چاپ("  مقدار شمارنده = " + شمارنده);
}

value.en:
// Explicit step (descending)
for (int counter = 10; counter > 0; step 2) {
    print(counter);
}

// Smart step (empty = auto-detect direction and step 1)
for (int counter = 0; counter < 4;) {
    print("  counter = " + counter);
}

// Explicit step
for (int counter = 34; counter > 3; step 3) {
    print("  counter value = " + counter);
}

value.ja:
// 明示的なステップ（降順）
for (整数 カウンタ = 10; カウンタ > 0; ステップ 2) {
    表示(カウンタ);
}

// スマートステップ（空 = 方向とステップ1を自動検出）
for (整数 カウンタ = 0; カウンタ < 4;) {
    表示("  カウンタ = " + カウンタ);
}

// 明示的なステップ
for (整数 カウンタ = 34; カウンタ > 3; ステップ 3) {
    表示("  カウンタの値 = " + カウンタ);
}

value.ru:
// Явный шаг (по убыванию)
для (цел счетчик = 10; счетчик > 0; шаг 2) {
    печать(счетчик);
}

// Умный шаг (пусто = автоопределение направления и шаг 1)
для (цел счетчик = 0; счетчик < 4;) {
    печать("  счетчик = " + счетчик);
}

// Явный шаг
для (цел счетчик = 34; счетчик > 3; шаг 3) {
    печать("  значение счетчика = " + счетчик);
}
